"""Self-contained BTC research bundle; no credentials or trading endpoints.
The source is compressed only for transport. It is SHA-256 checked and written
in readable form to research_output/research_source.py before execution.
"""
import base64, hashlib, runpy, sys, zlib
from pathlib import Path
SOURCE_SHA256 = '8792f94c50ef9ba9e903f1c60c5bc3436aa25c14a4f58ade875549695079cd5e'
PAYLOAD = ''''''
# Restore two transport characters if a text channel elides them; SHA below is authoritative.
PAYLOAD = PAYLOAD.replace('KZbMfvW6uMR5','KZbMfvW6vMR5')
source = zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(source).hexdigest() == SOURCE_SHA256, 'Source transport integrity failed'
out = Path(sys.argv[sys.argv.index('--out')+1]) if '--out' in sys.argv else Path('research_output')
out.mkdir(parents=True,exist_ok=True)
canonical = out / 'research_source.py'
canonical.write_bytes(source)
(out / 'research_source.sha256').write_text(SOURCE_SHA256+'\n')
runpy.run_path(str(canonical.resolve()), run_name='__main__')
